import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"住宅保障法","description":"","frontmatter":{},"headers":[],"relativePath":"ja/45-住房保障法.md","filePath":"ja/45-住房保障法.md","lastUpdated":1789183869000}'),i={name:"ja/45-住房保障法.md"};function e(o,t,n,h,s,b){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="住宅保障法" tabindex="-1">住宅保障法 <a class="header-anchor" href="#住宅保障法" aria-label="Permalink to &quot;住宅保障法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>プロジェクト</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>45</td></tr><tr><td>所属モジュール</td><td>法律体系と統治枠組み</td></tr><tr><td>コアキーワード</td><td>居住権、保障住宅、空間法的管轄、宜居環境、反投機</td></tr></tbody></table><h2 id="第一節-立法目的と基本原則" tabindex="-1">第一節 立法目的と基本原則 <a class="header-anchor" href="#第一節-立法目的と基本原則" aria-label="Permalink to &quot;第一節 立法目的と基本原則&quot;">​</a></h2><p>《住宅保障法》はアンカー共生文明の五部の付帯法の一つであり、衡元宙内のすべての生命の居住権を保障し、公平で持続可能な住宅保障体系を構築し、空間法的管轄技術を利用して万族に適した居住空間を提供し、住宅分野における投機と略奪を防止することを目的とする。</p><p>本法は以下の基本原則を確立する：</p><table tabindex="0"><thead><tr><th>原則</th><th>内包</th></tr></thead><tbody><tr><td>居住保障原則</td><td>各生命は適した居住空間を得る権利を有し、国家と文明は基本的な居住ニーズを保障する義務を有する</td></tr><tr><td>公益優先原則</td><td>住宅はまず生活必需品であり投機商品ではなく、保障住宅は公益属性を有する</td></tr><tr><td>空間効率原則</td><td>空間法的管轄技術を利用して空間利用効率を高め、宜居空間を拡張する</td></tr><tr><td>異族適応原則</td><td>異なる種族の生理的特性と生活習慣に応じて適応した居住空間を提供する</td></tr><tr><td>宜居環境原則</td><td>居住空間は良好な生態環境、インフラストラクチャ、公共サービスを備えるべきである</td></tr><tr><td>反投機原則</td><td>住宅を対象とした投機炒作を禁止し、住宅が富を略奪するツールとなることを防止する</td></tr></tbody></table><h2 id="第二節-居住権の法律保障" tabindex="-1">第二節 居住権の法律保障 <a class="header-anchor" href="#第二節-居住権の法律保障" aria-label="Permalink to &quot;第二節 居住権の法律保障&quot;">​</a></h2><p>本法は、居住権は共生憲法が各生命に付与した基本権利であり、具体的に以下を含むことを明確に規定する：</p><ol><li><strong>基本居住権</strong>: 各生命は最低基準を下回らない居住空間を得る権利を有し、最低基準は種族の体型と生活ニーズに応じて決定される。</li><li><strong>保障住宅申請権</strong>: 条件を満たす生命は保障住宅を申請する権利を有し、申請条件と配分基準は公開透明である。</li><li><strong>居住安全権</strong>: 居住空間は安全基準を満たさなければならず、危険住宅と居住に適さない空間は賃貸または配分してはならない。</li><li><strong>居住安定権</strong>: 保障住宅の居住者は条件を満たす場合に安定した居住権を享有し、恣意的に退去させてはならない。</li><li><strong>居住環境権</strong>: 居住者は清潔な空気、水源と良好な周辺環境を得る権利を有し、環境汚染に対して苦情を申し立てる権利を有する。</li><li><strong>住宅改造権</strong>: 居住者は建築の安全と他人の権益に影響を与えない前提で、居住空間に合理的な改造を行う権利を有する。</li></ol><h2 id="第三節-住宅保障体系" tabindex="-1">第三節 住宅保障体系 <a class="header-anchor" href="#第三節-住宅保障体系" aria-label="Permalink to &quot;第三節 住宅保障体系&quot;">​</a></h2><p>アンカー共生文明の住宅保障体系は三種類の住宅に分かれ、異なるニーズの層をカバーする：</p><table tabindex="0"><thead><tr><th>種類</th><th>名称</th><th>保障対象</th><th>配分方式</th><th>賃料/価格</th></tr></thead><tbody><tr><td>第一種</td><td>公共賃貸住宅</td><td>低所得層、初級修練者、新移民</td><td>申請審査制、順番待ち配分</td><td>象徴的な低賃料</td></tr><tr><td>第二種</td><td>共有持分住宅</td><td>中所得層、中級修練者</td><td>申請審査制、抽選配分</td><td>市場価格より低く、個人と国家の共有持分</td></tr><tr><td>第三種</td><td>商品住宅</td><td>高所得層、高階修練者</td><td>市場取引</td><td>市場価格、規制の制約を受ける</td></tr></tbody></table><p>さらに、空間折りたたみ技術を利用して「空間折りたたみ居住区」を建設する：限られた物理的空間内で空間折りたたみ技術により居住面積を拡張し、高密度地域により多くの居住空間を提供する。空間折りたたみ居住区は安全評価を経なければならず、空間の安定性を確保する。</p><h2 id="第四節-異族住宅適応" tabindex="-1">第四節 異族住宅適応 <a class="header-anchor" href="#第四節-異族住宅適応" aria-label="Permalink to &quot;第四節 異族住宅適応&quot;">​</a></h2><p>衡元宙内の異なる種族の特殊な居住ニーズに対応するため、本法は異族住宅適応制度を設立する：</p><ul><li><strong>水生種族</strong>: 水中居住空間または水陸両用住宅を提供し、水循環と水質維持システムを備える。</li><li><strong>飛行種族</strong>: 高高度居住空間または離発着プラットフォーム付き住宅を提供し、航空交通管理を備える。</li><li><strong>エネルギー生命</strong>: エネルギー濃度が適した居住空間を提供し、エネルギー安定装置を備える。</li><li><strong>巨大種族</strong>: 大規模な居住空間を提供し、建築構造は特別に補強される。</li><li><strong>微型種族</strong>: 微型居住区を提供し、スケーリングチャネルと専用施設を備える。</li></ul><p>異族住宅適応基準は住宅主管部門が各族代表と共同で制定し、定期的に更新する。</p><h2 id="第五節-住宅建設と管理" tabindex="-1">第五節 住宅建設と管理 <a class="header-anchor" href="#第五節-住宅建設と管理" aria-label="Permalink to &quot;第五節 住宅建設と管理&quot;">​</a></h2><ul><li><strong>住宅建設計画</strong>: 国家は人口増加と移民状況に応じて住宅建設計画を制定し、住宅の供給と需要のバランスを確保する。</li><li><strong>建設基準</strong>: 保障住宅の建設は安全、環境、宜居の基準を満たさなければならず、建設の質を低下させることを禁止する。</li><li><strong>財産管理</strong>: 居住区は自治管理と専門的な財産管理を組み合わせたモデルを実施し、居住者は財産管理の決定に参加する権利を有する。</li><li><strong>住宅修繕</strong>: 保障住宅の修繕は住宅管理機構が責任を負い、修繕資金は公共積立から支出される。</li><li><strong>退出机制</strong>: 保障住宅の居住者の収入または修練レベルが保障基準を超えた場合、保障住宅を退出するか商品住宅に転換すべきであり、退出には合理的な移行期間が与えられる。</li></ul><h2 id="第六節-反投機と監督" tabindex="-1">第六節 反投機と監督 <a class="header-anchor" href="#第六節-反投機と監督" aria-label="Permalink to &quot;第六節 反投機と監督&quot;">​</a></h2><p>住宅分野における投機と略奪を防止するため、本法は以下の監督措置を設立する：</p><ol><li>個人が保有する商品住宅の数を制限し、限度額を超えた部分には累進的な住宅税を徴収する。</li><li>保障住宅の転貸と転売を禁止し、違反者は保障資格を取り消され住宅を回収される。</li><li>住宅取引情報公開制度を構築し、暗箱操作と価格操作を防止する。</li><li>不動産開発業者に対して資質管理と資金監督を実施し、未完成と詐欺を防止する。</li><li>住宅苦情と紛争解決机制を設立し、居住者の合法的な権益を保障する。</li></ol><h2 id="第七節-法律責任" tabindex="-1">第七節 法律責任 <a class="header-anchor" href="#第七節-法律責任" aria-label="Permalink to &quot;第七節 法律責任&quot;">​</a></h2><p>本法の規定に違反する行為は、情状の軽重に応じて以下の責任を負う：</p><ul><li>違反して保障住宅を配分した場合、是正を命じ責任者に処分を与える。</li><li>保障住宅を転貸、転売した場合、保障資格を取り消し、住宅を回収し罰金を科す。</li><li>開発業者が建設の質を低下させた場合、やり直しを命じ罰金を科し、情状が深刻な場合は資質を取り消す。</li><li>住宅投機炒作を行った場合、高額な投機税を徴収し罰金を科す。</li><li>危険住宅を賃貸して居住者に損害を与えた場合、賠償責任を負い、情状が深刻な場合は刑事責任を追及する。</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>《住宅保障法》はアンカー共生文明の「人人有路」理念の居住分野における実施である。それは分類された住宅保障体系を構築し、空間法的管轄技術を利用して居住空間を拡張し、異族の居住ニーズに適応し、住宅投機を取り締まることにより、各生命が安全で適した安定した家を持てることを確保し、万族共進のために安居保障を提供する。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>40-共生宪法总纲 (共生憲法総綱)</li><li>39-住房与环境保障 (住宅と環境保障)</li><li>13-空间法理调度体系详解 (空間法的管轄体系詳解)</li><li>46-环境保护法 (環境保護法)</li></ul>',29)])])}const u=a(i,[["render",e]]);export{g as __pageData,u as default};
